import{_ as s,C as t,o as n,c as r,av as d,E as o,j as i}from"./chunks/framework.BPJ8Zp9i.js";const b=JSON.parse('{"title":"주소","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"tag":"address","pageTitle":"주소 - Hans API"},"relativePath":"apis/address.md","filePath":"apis/[tag].md"}'),l={name:"apis/address.md"};function c(p,a,g,h,u,_){const e=t("ApiOperation");return n(),r("div",null,[a[0]||(a[0]=d(`<h1 id="주소" tabindex="-1">주소 <a class="header-anchor" href="#주소" aria-label="Permalink to &quot;주소&quot;">​</a></h1><p>주소(<code>/address</code>) 그룹입니다. <strong>지역 코드</strong>(시도·시군구)와 <strong>영문 주소 검색</strong> 두 가지를 담습니다.</p><h2 id="영문-주소-검색" tabindex="-1">영문 주소 검색 <a class="header-anchor" href="#영문-주소-검색" aria-label="Permalink to &quot;영문 주소 검색&quot;">​</a></h2><p>도로명주소 개발자센터(juso.go.kr)의 <strong>영문 주소 검색</strong> API입니다. 한글 주소를 넣으면 공식 <strong>영문 표기</strong>로 바꿔 줍니다.</p><div class="tip custom-block"><p class="custom-block-title">주소는 지어내면 안 됩니다</p><p>로마자 표기는 규칙이 까다로워(<code>중앙대로1985번길</code> → <code>Jungang-daero 1985beon-gil</code>) 임의로 만들면 틀립니다. 이 API 는 국가가 관리하는 <strong>공식 표기</strong>를 그대로 가져옵니다.</p></div><h2 id="한글-→-영문" tabindex="-1">한글 → 영문 <a class="header-anchor" href="#한글-→-영문" aria-label="Permalink to &quot;한글 → 영문&quot;">​</a></h2><p>한글 주소를 <code>keyword</code> 로 검색하면, 매칭되는 주소를 한글·영문 함께 돌려줍니다. 영문은 <strong>순서가 뒤집힙니다</strong> — 한글은 큰 단위→작은 단위, 영문은 작은 단위→큰 단위입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>부산광역시 금정구 중앙대로1985번길 1</span></span>
<span class="line"><span>1 Jungang-daero 1985beon-gil, Geumjeong-gu, Busan</span></span></code></pre></div><p>시/도, 시/군/구, 읍/면/동도 각각 영문으로 쪼개 줍니다(<code>sido</code>, <code>sigungu</code>, <code>eupmyeondong</code>).</p><h2 id="검색-제약" tabindex="-1">검색 제약 <a class="header-anchor" href="#검색-제약" aria-label="Permalink to &quot;검색 제약&quot;">​</a></h2><p><strong>시/도명 단독·한 글자·숫자만으로는 검색되지 않습니다.</strong> 도로명주소 API 자체의 제약이며, 이 경우 <code>400</code> 을 반환합니다. 결과가 없을 때는 에러가 아니라 <strong>빈 목록</strong>입니다.</p><h2 id="데이터-출처" tabindex="-1">데이터 출처 <a class="header-anchor" href="#데이터-출처" aria-label="Permalink to &quot;데이터 출처&quot;">​</a></h2><ul><li>행정안전부 <strong>도로명주소 영문 검색 API</strong> (juso.go.kr)</li></ul><div id="op-RegionController_list" class="oa-op-anchor"></div>`,14)),o(e,{"operation-id":"RegionController_list"}),a[1]||(a[1]=i("div",{id:"op-AddressController_searchEnglish",class:"oa-op-anchor"},null,-1)),o(e,{"operation-id":"AddressController_searchEnglish"})])}const f=s(l,[["render",c]]);export{b as __pageData,f as default};
